#!/usr/bin/env bash
# ci-walden tenant-interface v6 — generated by ci-walden tenant-init
# stack: verify-json (verify.json defines the gate; this file only runs it)
# contract: bash at repo root; exit status is the verdict (0 = green)
# regenerating this file on an unchanged repo is a no-op diff
# conformance: sha256:a45d2b150685bed6aee4e4cf6450305204d3d937c86992bfc0f5ca2bc4417ff0
set -eo pipefail
# The gate is defined once, in verify.json at the repo root. This file
# only runs it, so the desk and CI execute the same command. Checks go
# in verify.json; machine setup goes in ci-walden/provision.sh.

# ci_walden_field <key>: print the string at verify.json[key], or fail.
ci_walden_field() {
  if command -v python3 >/dev/null 2>&1; then
    python3 -c '
import json, sys
v = json.load(open("verify.json")).get(sys.argv[1])
if not isinstance(v, str) or not v.strip():
    sys.exit(3)
sys.stdout.write(v)' "$1"
  elif command -v node >/dev/null 2>&1; then
    node -e '
const v = JSON.parse(require("fs").readFileSync("verify.json", "utf8"))[process.argv[1]];
if (typeof v !== "string" || !v.trim()) process.exit(3);
process.stdout.write(v);' "$1"
  elif command -v jq >/dev/null 2>&1; then
    jq -ej --arg k "$1" '.[$k] | strings | select(test("\\S"))' verify.json
  else
    echo "ci-walden: python3, node, or jq is needed to read verify.json" >&2
    return 4
  fi
}

if [ ! -f verify.json ]; then
  echo "ci-walden: verify.json is missing at the repo root; run 'ci-walden tenant-init --bootstrap'" >&2
  exit 2
fi
if ! ci_walden_cmd=$(ci_walden_field verify); then
  echo "ci-walden: verify.json has no usable \"verify\" command" >&2
  exit 2
fi

# Provisioning is for machines with nothing set up yet: the CI runner
# (which exports CI_WALDEN_SHA) or a clean-room run. A desk keeps its
# own configuration.
if [ -n "${CI_WALDEN_SHA:-}${CI_WALDEN_CLEAN_ROOM:-}" ] && [ -f ci-walden/provision.sh ]; then
  echo "ci-walden: provision — ci-walden/provision.sh"
  . ci-walden/provision.sh
fi

echo "ci-walden: verify — $ci_walden_cmd"
eval "$ci_walden_cmd"
